export class AsyncMutex {
  private locks: number = 0;
  private queue: (() => void)[] = [];

  async acquire(): Promise<()=>void> {
    if (this.locks === 0) {
      this.locks++;
      return () => {};
    }
    const cb = await new Promise<void>(resolve => this.queue.push(resolve));
    this.locks++;
    return cb;
  }

  release(cb: ()=>void) {
    cb();
    this.locks--;
    this.queue.splice(0, Math.min(this.queue.length, this.locks));
  }
}
